class Command(BaseCommand):
    help = "Seed all 32 RS Engine rules and exact field schemas into the database"

    def handle(self, *args, **options):
        rules_data = json.loads(RULES_RAW)
        rules_created = 0
        rules_updated = 0

        self.stdout.write("Seeding rules and field schemas from catalog...")
        for item in rules_data:
            rule, created = Rule.objects.update_or_create(
                key=item["key"],
                defaults={
                    "name": item["name"],
                    "description": item["description"],
                    "category": item["category"],
                    "rule_type": item["rule_type"],
                    "display_order": item["display_order"],
                    "is_active": item["is_active"],
                    "is_disabled": item["is_disabled"],
                    "field_schema": item["field_schema"],
                },
            )
            if created:
                rules_created += 1
            else:
                rules_updated += 1

        self.stdout.write(
            self.style.SUCCESS(
                f"Successfully seeded rules: {rules_created} created, {rules_updated} updated. Total: {Rule.objects.count()}"
            )
        )